	protected Underwriter read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Underwriter" );

		Underwriter entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Underwriter with primary key" );
		msg.append( underwriterId );
		
		UnderwriterFetchOneSummary fetchOneSummary = new UnderwriterFetchOneSummary( underwriterId );

		try {
			entity = UnderwriterService.getUnderwriterInstance().getUnderwriter( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Underwriter " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Underwriter.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Underwriter." );

		StringBuilder msg = new StringBuilder( "Failed to update a Underwriter : " );        
		Underwriter entity = read();
		UpdateUnderwriterCommand command = generateUpdateCommand();
		command.setUnderwriterId(entity.getUnderwriterId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Underwriter." );

			// for use later on...
			underwriterId = entity.getUnderwriterId();

			UnderwriterService proxy = UnderwriterService.getUnderwriterInstance();  

			proxy.updateUnderwriter( command ).get();

			LOGGER.info( "-- Successfully saved Underwriter - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + underwriterId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Underwriter.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Underwriter." );

		Underwriter entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Underwriter with id " + underwriterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Underwriter with id " + underwriterId );

			throw e;
		}

		try{
			UnderwriterService.getUnderwriterInstance().delete( new DeleteUnderwriterCommand( entity.getUnderwriterId() ) ).get();
			LOGGER.info( "-- Successfully deleted Underwriter with id " + underwriterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Underwriter with id " + underwriterId );

			throw e;
		}
	}

	/**
	 * get all Underwriters.
	 */
	protected List<Underwriter> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Underwriters:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Underwriter : " );        
		List<Underwriter> collection  = new ArrayList<>();

		try {
			// call the static get method on the UnderwriterService
			collection = UnderwriterService.getUnderwriterInstance().getAllUnderwriter();
			assertNotNull( collection, "An Empty collection of Underwriter was incorrectly returned.");
			
			// Now print out the values
			Underwriter entity = null;            
			Iterator<Underwriter> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getUnderwriterId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

